#include <stdio.h>
#define IS_INT(e) _Generic((e), int: 1, default: 0)
int main(void)
{
    _Static_assert(IS_INT(+3) && IS_INT(-3) && IS_INT(3 - 2), "unary and arithmetic types");
    _Static_assert(IS_INT(5 < 8) && IS_INT(5 <= 8) && IS_INT(5 > 8) && IS_INT(5 >= 8), "relational types");
    _Static_assert(IS_INT(5 == 8) && IS_INT(5 != 8), "equality types");
    _Static_assert(IS_INT(!2) && IS_INT(2 && 1) && IS_INT(2 || 0), "logical types");
    int number_0 = 0;
    printf("number=0: digit=%d, prefix=%d, by2=%d\n", number_0 % 10, number_0 / 10, number_0 % 2);
    int number_1 = 1;
    printf("number=1: digit=%d, prefix=%d, by2=%d\n", number_1 % 10, number_1 / 10, number_1 % 2);
    int number_2 = 8;
    printf("number=8: digit=%d, prefix=%d, by2=%d\n", number_2 % 10, number_2 / 10, number_2 % 2);
    int number_3 = 9;
    printf("number=9: digit=%d, prefix=%d, by2=%d\n", number_3 % 10, number_3 / 10, number_3 % 2);
    int number_4 = 10;
    printf("number=10: digit=%d, prefix=%d, by2=%d\n", number_4 % 10, number_4 / 10, number_4 % 2);
    int number_5 = 19;
    printf("number=19: digit=%d, prefix=%d, by2=%d\n", number_5 % 10, number_5 / 10, number_5 % 2);
    int number_6 = 247;
    printf("number=247: digit=%d, prefix=%d, by2=%d\n", number_6 % 10, number_6 / 10, number_6 % 2);
    int number_7 = 250;
    printf("number=250: digit=%d, prefix=%d, by2=%d\n", number_7 % 10, number_7 / 10, number_7 % 2);
    int number_8 = 32767;
    printf("number=32767: digit=%d, prefix=%d, by2=%d\n", number_8 % 10, number_8 / 10, number_8 % 2);
    printf("negative exception: -3 / 2=%d, -3 %% 2=%d\n", -3 / 2, -3 % 2);
    int compared_0 = 5;
    int limit_0 = 8;
    printf("compare 5,8: %d %d %d %d %d %d\n", compared_0 < limit_0, compared_0 <= limit_0, compared_0 > limit_0, compared_0 >= limit_0, compared_0 == limit_0, compared_0 != limit_0);
    int compared_1 = 5;
    int limit_1 = 5;
    printf("compare 5,5: %d %d %d %d %d %d\n", compared_1 < limit_1, compared_1 <= limit_1, compared_1 > limit_1, compared_1 >= limit_1, compared_1 == limit_1, compared_1 != limit_1);
    int compared_2 = 9;
    int limit_2 = 8;
    printf("compare 9,8: %d %d %d %d %d %d\n", compared_2 < limit_2, compared_2 <= limit_2, compared_2 > limit_2, compared_2 >= limit_2, compared_2 == limit_2, compared_2 != limit_2);
    int compared_3 = 0;
    int limit_3 = 0;
    printf("compare 0,0: %d %d %d %d %d %d\n", compared_3 < limit_3, compared_3 <= limit_3, compared_3 > limit_3, compared_3 >= limit_3, compared_3 == limit_3, compared_3 != limit_3);
    int compared_4 = -1;
    int limit_4 = 0;
    printf("compare -1,0: %d %d %d %d %d %d\n", compared_4 < limit_4, compared_4 <= limit_4, compared_4 > limit_4, compared_4 >= limit_4, compared_4 == limit_4, compared_4 != limit_4);
    int compared_5 = 0;
    int limit_5 = -1;
    printf("compare 0,-1: %d %d %d %d %d %d\n", compared_5 < limit_5, compared_5 <= limit_5, compared_5 > limit_5, compared_5 >= limit_5, compared_5 == limit_5, compared_5 != limit_5);
    int left_0 = 0;
    int right_0 = 0;
    printf("logic 0,0: %d %d %d %d %d\n", !left_0, !right_0, left_0 && right_0, left_0 || right_0, left_0 && !right_0);
    int left_1 = 0;
    int right_1 = 1;
    printf("logic 0,1: %d %d %d %d %d\n", !left_1, !right_1, left_1 && right_1, left_1 || right_1, left_1 && !right_1);
    int left_2 = 1;
    int right_2 = 0;
    printf("logic 1,0: %d %d %d %d %d\n", !left_2, !right_2, left_2 && right_2, left_2 || right_2, left_2 && !right_2);
    int left_3 = 1;
    int right_3 = 1;
    printf("logic 1,1: %d %d %d %d %d\n", !left_3, !right_3, left_3 && right_3, left_3 || right_3, left_3 && !right_3);
    int left_4 = 2;
    int right_4 = 1;
    printf("logic 2,1: %d %d %d %d %d\n", !left_4, !right_4, left_4 && right_4, left_4 || right_4, left_4 && !right_4);
    int left_5 = 2;
    int right_5 = 0;
    printf("logic 2,0: %d %d %d %d %d\n", !left_5, !right_5, left_5 && right_5, left_5 || right_5, left_5 && !right_5);
    int left_6 = -2;
    int right_6 = 5;
    printf("logic -2,5: %d %d %d %d %d\n", !left_6, !right_6, left_6 && right_6, left_6 || right_6, left_6 && !right_6);
    puts("all result type assertions passed");
    return 0;
}
